const e=["Dieu","Justice","Religion","Force","Lorus","Histoire"],t="Dieu de la Justice",i=["Edes représente la Justice, une Force de la Conscience.","Il est l'une des divinités les plus importantes de l'histoire humaine.","Son culte est intimement lié à la naissance de Lorus, le premier grand royaume humain, et à la rébellion contre la domination des Dragons.","Pourtant, l'histoire d'Edes est aussi celle d'une contradiction.","Celui qui combattit autrefois pour libérer les hommes finit par considérer leur liberté comme une possible source d'injustice."],n=[{label:"Domaines",value:"Justice"},{label:"Symboles",value:"Une épée, une balance, une lame lumineuse, un bouclier, une couronne, une main ouverte"}],s=[{title:"La Justice",title_border:"#e8553d",type:"text",content:["La Justice ne signifie pas simplement appliquer une loi.","Une loi peut être injuste.","Une décision peut être légale sans être juste.","Pour Edes, la Justice repose d'abord sur une idée simple :"]},{title:"",type:"banner",content:"Protéger celui qui ne peut pas se défendre. Punir celui qui abuse de son pouvoir. Et reconnaître ses propres erreurs.",subtitle:"À noter"},{title:"",type:"text",content:["Cette conception est à l'origine de son influence sur les premiers humains.","Elle deviendra également la source de sa propre contradiction."]},{title:"La Rébellion des Valm",title_border:"#c2660a",type:"text",content:["Durant l'Âge des Dragons, les humains vivaient sous la domination des grandes civilisations draconiques.","Lorsque plusieurs communautés humaines décidèrent de se soulever, elles cherchèrent l'aide d'Edes.","Le dieu ne leur offrit pas une arme capable de vaincre les Dragons.","Il les aida à s'unir.","Les humains apprirent à combattre ensemble, à organiser leurs forces et à défendre un avenir commun.","La victoire mit fin à la domination des Dragons.","Elle entraîna cependant leur quasi-disparition.","Cette période marque le début de l'histoire connue des humains."]},{title:"Le premier roi de Lorus",title_border:"#6f9fd8",type:"text",content:["Après la victoire, Edes ne quitta pas les humains.","Il resta parmi eux et devint le premier roi du Royaume Saint de Lorus.","Les premiers temps du royaume furent profondément marqués par sa vision de la Justice.","La Loi devait protéger.","Le pouvoir devait avoir des limites.","Les faibles devaient pouvoir être défendus.","Et ceux qui gouvernaient devaient eux-mêmes être soumis à la Justice.","Pendant longtemps, Edes sembla incarner exactement les idéaux qui avaient conduit les humains à se libérer des Dragons."]},{title:"La transformation d'Edes",title_border:"#e8553d",type:"text",content:["Les siècles passèrent.","Edes changea.","Celui qui avait autrefois combattu pour libérer les hommes commença à considérer la liberté comme une menace lorsqu'elle risquait de produire l'injustice.","Sa pensée évolua progressivement :","« Une menace doit être neutralisée avant d'agir. »","Puis :","« Ceux qui pourraient devenir dangereux doivent être surveillés. »","Et finalement :","« La sécurité du royaume passe avant la liberté individuelle. »","Edes ne considéra jamais cette évolution comme une trahison de ses principes.","Au contraire.","Il pensait toujours protéger les hommes.","C'est précisément ce qui rend sa transformation tragique."]},{title:"Edes et Lorus",title_border:"#c2660a",type:"text",content:["Lorus finit par devenir une société profondément organisée autour de la Loi.","La Justice, la sécurité et l'obéissance furent progressivement liées les unes aux autres.","La Loi ne servait plus seulement à punir l'injustice.","Elle devait empêcher qu'elle puisse apparaître.","Ainsi naquit une interprétation radicale de la Justice."]},{title:"",type:"banner",content:"Edes représente la Justice. Lorus représente progressivement une interprétation déformée de la Justice.",subtitle:"À noter"},{title:"",type:"text",content:["Le royaume devint sûr, puissant et profondément religieux.","Mais la Loi ne protégeait plus seulement les hommes.","Elle commença également à les surveiller."]},{title:"Edes et Théomis",title_border:"#6f9fd8",type:"text",content:["La relation entre Edes et Théomis est devenue fondamentale dans la culture de Lorus.","La Justice détermine ce qui est juste.","L'Ordre fournit les structures permettant de l'appliquer.","Durant les premiers temps de Lorus, ces deux principes se complétaient.","Avec le temps, ils furent progressivement confondus.","La Loi devint l'expression de la Justice.","L'obéissance devint une preuve de loyauté.","La stabilité devint une condition de la paix.","Cette évolution appartient aux mortels.","Mais Edes lui-même finit par l'accepter."]},{title:"Edes et les autres dieux",title_border:"#e8553d",type:"text",content:["Edes entretient une relation complexe avec Neien.","Tous deux représentent des Forces de la Conscience liées à la manière dont les mortels traitent leurs semblables.","Justice et Miséricorde peuvent se compléter.","Elles peuvent également entrer en conflit.","Faut-il punir celui qui a commis une faute ?","Ou lui accorder une seconde chance ?","Cette opposition deviendra particulièrement importante dans l'histoire de Neien.","Avec Théomis, Edes partage une relation plus complémentaire.","Avec Fauscht, il partage une autre contradiction : la Justice cherche à déterminer ce qui doit être fait, tandis que la Mort finit par toucher tous les êtres indépendamment de leurs mérites."]},{title:"Symboles",title_border:"#c2660a",type:"text",content:"Edes est généralement représenté par :"},{title:"",type:"list",content:["Une épée","Une balance","Une lame lumineuse","Un bouclier","Une couronne","Une main ouverte"]},{title:"",type:"text",content:["L'épée représente la capacité à agir.","La balance représente le jugement.","Le bouclier représente la protection.","Dans les représentations les plus anciennes, Edes porte rarement une couronne.","Les représentations postérieures à la fondation de Lorus le montrent beaucoup plus souvent comme un roi.","Cette différence n'est peut-être pas anodine."]},{title:"Aujourd'hui",title_border:"#6f9fd8",type:"text",content:["Edes demeure le cœur spirituel de Lorus.","Son nom est invoqué par les magistrats, les soldats et les membres du Culte de la Lame Radieuse.","Pour les citoyens de Lorus, il reste le dieu qui libéra leurs ancêtres.","Pour leurs opposants, son nom peut évoquer une tout autre réalité : celle d'un royaume où la Justice est devenue impossible à distinguer de la Loi.","Mais Edes demeure le dieu de la Justice.","Et personne ne sait exactement à quel moment le roi de Lorus cessa de comprendre ce que ce mot signifiait."]}],r=["Les Dieux","Les Forces de la Conscience","Théomis","Neien","Fauscht","Lorus","La Rébellion des Valm","La Fondation de Lorus","Culte de la Lame Radieuse"],a={tags:e,surname:t,presentation:i,infos:n,sections:s,related:r};export{a as default,n as infos,i as presentation,r as related,s as sections,t as surname,e as tags};
